from audit_utils import *
from collections import Counter
import csv
for tree,layer in [('fr_printed','French as printed'),('fr','French corrected')]:
    rel=f'sources/{tree}/fr/236.tex'
    def r(a,b,line,why,kind='reading',count=1):
        replace(rel,a,b,layer,'236-226',line,'1.1, 1.4',
                'Scan leaf 7 at 400 dpi, full page and three enlarged bands: '+why,kind=kind,count=count)
    s,_,_=page_text(rel,226)
    for a,b,body in list(footnotes(s)):
        r(s[a:b],'','definition of the two torsion loci','The edition footnote explaining X is not printed; the correction belongs in the external ledger and notes.','structure')
    r(r'envoie $x$ dans $G^\circ$.',r'envoie $x$ dans $G$,','definition of nu','The print has G with no circle and a comma before capitalized Donc.')
    r(r'est formé des $x\in G$',r'est formé des $x\in X$','two loci following the definition','The printed ambient letter is X.')
    r('$p$ (resp. une puissance de $p$), et','$p$ (resp. une puissance de $p$) et','two loci following the definition','There is no comma after the closing parenthesis.')
    r('La fonction $\\nu$ sur $G^\\tau$ est localement\nconstructible.',underline_prose('La fonction $\\nu$ sur $G^\\tau$ est localement constructible.'),'lemma 1.4','All statement prose is straight underlined, with symbols outside the emphasis.')
    r(r'$x\in G^\tau$ tels que $\nu(x)=n$ est',r'$x\in G^\tau$, tels que $\nu(x)=n$, est','proof of 1.4','The print has commas before and after the relative clause.')
    r('même des\n$\\varphi_d^{-1}(G^\\circ)$','même des\n$\\varphi_i^{-1}(G^\\circ)$','proof of 1.4, final inverse image','The final subscript is i, the generic index, not d.')
    r("générisation $x'$ de $x$ dans $G^\\sigma$ au-dessus de $y'$. Cela", "générisation $x'$ de $x$ dans $G$ au-dessus de $y'$. Cela",'openness proof, required generization','This first required-generization sentence is printed with plain G.')
    r('i.e.','i. e.','openness proof','The abbreviation has an intervening space.')
    r(r'\longrightarrow',r'\to ','three arrows','The arrows are short.',count=3)
    r("de $y'$ ; elle", "de $y'$, elle",'characteristic-zero case','The punctuation is a comma, not a semicolon.')
    r("$G_{y'}^\\sigma=G_{y'}^\\tau$. Si", "$G_{y'}^\\sigma=G_{y'}^\\tau$, Si",'characteristic-zero case, last equality','The scan has a comma before capitalized Si.')
    if tree=='fr':
        r(r'envoie $x$ dans $G$,',r'envoie $x$ dans $G^\circ$,','definition of nu','The minimum is the order of the component class, so the target must be the identity component. With plain G every power already belongs to G and the minimum would be 1; a nonidentity point of a constant cyclic group gives an immediate counterexample.','misprint of the original')
        r(r'est formé des $x\in X$',r'est formé des $x\in G^\tau$','two loci following the definition','X is undefined. The preceding sentence defines nu precisely for x in G tau, the common ambient locus of the two subloci; using that domain repairs the undefined letter and keeps the predicate meaningful. The existing edition had changed X to G, whose intended restriction is made explicit here.','misprint of the original')
        r("générisation $x'$ de $x$ dans $G$ au-dessus de $y'$. Cela", "générisation $x'$ de $x$ dans $G^\\sigma$ au-dessus de $y'$. Cela",'openness proof, required generization','The goal is openness of G sigma to S, so the lifted generization must lie in G sigma. Existence merely in G is already supplied by the universal openness hypothesis and cannot establish the stated reduction. The subsequent characteristic-zero and positive-characteristic arguments explicitly secure membership in G sigma.','misprint of the original')
    upright_page(rel,layer,'236-226')
event('236-1.4-definition','refuted, with the refined statement\'s id','Printed definition sends x into G, which makes nu identically 1. For a nonidentity point of a constant cyclic group the component order is not 1. Refined statement 236-1.4-definition-corrected uses the minimum positive n carrying x into G zero; the next undefined X is replaced by the already specified domain G tau. The unprinted explanatory footnote is removed from both text layers.','236, p. 226, paragraph before lemma 1.4')
event('236-1.4-definition-corrected','independent re-proof','For a point in the torsion-component locus the minimum positive n with x^n in the identity component is exactly the order of its component class. Its being prime to p or a power of p gives respectively G sigma and G rho. This checks the refined definition and both predicates; the printed no-circle definition cannot do so.','236, p. 226, paragraph before lemma 1.4')
event('236-1.4','targeted proof check','For fixed n, the order-n locus is phi_n inverse(G zero) minus the finite union of phi_d inverse(G zero) over proper divisors d of n, so is locally constructible. On a Noetherian affine open, constructible level sets imply finitely many values: a level set containing each generic point contains a dense open, and Noetherian induction handles the proper closed complement. The prime-to-characteristic test for a fixed n is pulled back from D(n); the p-power test is all the base when n=1, empty if n is not a prime power, and V(p) when n is a positive power of a single prime p. Thus both loci are locally constructible, including in mixed characteristic.','236, p. 226, lemma 1.4 and its application')
event('236-1.1-closed-loci','targeted proof check','When G zero is closed, G tau is specialization-stable as a union of its inverse images under positive power maps; its openness makes it locally constructible, hence it is closed. The same reasoning applies to G sigma in equal characteristic and to G rho: generic characteristic zero contributes only G zero to G rho, while positive characteristic stays the same under specialization. Combined with the locally constructible loci just checked, this establishes the closedness assertions.','236, p. 226, opening two paragraphs')
event('236-1.1-sigma-open-reduction','targeted proof check','Checked why the sought lift must be in G sigma, rather than merely G, and the characteristic-zero case: any generization lies in the open G tau and G sigma equals G tau on a characteristic-zero fibre. The valuative base reduction and further change making a section are standard inputs carried as background. The positive-characteristic argument begins with nu(g(y prime))=p^h m and continues on the next page; m and its coprimality are correctly printed.','236, p. 226, final paragraph and display')
